<section class="ch-hero"><div class="ch-dots" aria-hidden="true"></div><div class="ch-w ch-hero-g"><div class="ch-hero-t"><p class="ch-tag">The sauce that ties the meal together</p><h1>Chut<span>ney</span></h1><p class="ch-hero-s">sweet &middot; sour &middot; spicy</p><p class="ch-lead">A bright, practical guide to chutneys: fresh green ones blitzed in a minute, slow-cooked fruit ones that keep for months, and which to spoon beside every dish.</p><div class="ch-hero-a"><a class="ch-btn" href="#match">Match my dish</a><a class="ch-btn ch-btn-o" href="#batch">Plan a batch</a></div></div>
<div class="ch-hero-v"><figure class="ch-plate"><img src="https://images.unsplash.com/photo-1743615467363-250466982515?auto=format&fit=crop&w=560&h=560&q=75" alt="a dosa served with three dipping sauces" width="560" height="560" fetchpriority="high"></figure><figure class="ch-plate ch-plate-s"><img src="https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=300&h=300&q=75" alt="golden fried samosas on a wooden tray" width="300" height="300" fetchpriority="high"></figure><svg viewBox="0 0 160 200" class="ch-jar ch-hj1" aria-hidden="true"><defs><clipPath id="ch-hj1-c"><path d="M30 50h100v120q0 20-20 20H50q-20 0-20-20z"/></clipPath></defs><rect x="40" y="18" width="80" height="26" rx="5" class="lid"/><path d="M30 50h100v120q0 20-20 20H50q-20 0-20-20z" class="gl"/><g clip-path="url(#ch-hj1-c)"><rect x="20" y="60" width="120" height="140" class="fill" style="fill:#2F8F5B"/><path class="wv" d="M0 64q20-10 40 0t40 0 40 0 40 0 40 0v20H0z" style="fill:#2F8F5B"/></g><rect x="44" y="104" width="72" height="40" rx="4" class="lb"/><text x="80" y="129">PUDINA</text></svg><svg viewBox="0 0 160 200" class="ch-jar ch-hj2" aria-hidden="true"><defs><clipPath id="ch-hj2-c"><path d="M30 50h100v120q0 20-20 20H50q-20 0-20-20z"/></clipPath></defs><rect x="40" y="18" width="80" height="26" rx="5" class="lid"/><path d="M30 50h100v120q0 20-20 20H50q-20 0-20-20z" class="gl"/><g clip-path="url(#ch-hj2-c)"><rect x="20" y="60" width="120" height="140" class="fill" style="fill:#F2A21B"/><path class="wv" d="M0 64q20-10 40 0t40 0 40 0 40 0 40 0v20H0z" style="fill:#F2A21B"/></g><rect x="44" y="104" width="72" height="40" rx="4" class="lb"/><text x="80" y="129">AAM</text></svg><span class="ch-chip ch-chip-a">fresh</span><span class="ch-chip ch-chip-b">cooked</span></div></div></section>

